                     <button id="continuetosignin" disabled="true" style="display: flex; align-items: center; justify-content: center; padding: 14px 40px; background-color: rgb(176, 190, 197); color: rgb(255, 255, 255); border-width: medium; border-style: none; border-color: currentcolor; border-image: initial; border-radius: 6px; font-size: 15px; font-weight: 700; cursor: not-allowed;">
                        Continue to Sign In
                        <svg width="18" height="18" viewBox="0 0 18 18" fill="none" style="margin-left: 8px;">
                           <path d="M5 9h8M9 5l4 4-4 4" stroke="white" stroke-width="1.8" stroke-linecap="round"></path>
                        </svg>
                     </button>
                     <script>
                        const IhaveRead = document.querySelector("#IhaveRead");
                        const signInButton = document.querySelector("#continuetosignin");
                        const skipfrlater = document.querySelector("#skipfrlater");
                        IhaveRead.addEventListener('click', (e)=> {
                            signInButton.disabled = false;
                            signInButton.style.backgroundColor = 'rgb(73, 47, 36)'; 
                            signInButton.style.cursor = 'pointer';
                        });

                        skipfrlater.addEventListener('click', (e)=> {
                            signInButton.disabled = false;
                            signInButton.style.backgroundColor = 'rgb(73, 47, 36)'; 
                            signInButton.style.cursor = 'pointer';
                            document.querySelector('#dispwarning').style.display = '';
                        });
                        signInButton.addEventListener('click',(e)=> {
                            location.href="/assignments/sign-in";
                        })
